import React, { useState, useCallback } from 'react';
import { ClientPanel } from './components/ClientPanel';
import { AdminPanel } from './components/AdminPanel';
import { ParticleOverlay } from './components/ParticleOverlay';
import { Order, Notification, ChartData } from './types';

export default function App() {
  const [activeParticles, setActiveParticles] = useState<number[]>([]);
  const [revenue, setRevenue] = useState(12450);
  const [orderCounter, setOrderCounter] = useState(1245);

  // Initial Mock Data
  const [orders, setOrders] = useState<Order[]>([
    { id: '1244', product: 'Espresso', amount: 45, time: '10:42', status: 'Completed' },
    { id: '1243', product: 'Latte', amount: 65, time: '10:30', status: 'Completed' },
    { id: '1242', product: 'Americano', amount: 40, time: '10:15', status: 'Completed' },
  ]);

  const [notifications, setNotifications] = useState<Notification[]>([
    { id: 'n1', title: 'System Ready', message: 'All services operational.', time: '09:00' }
  ]);

  const [chartData, setChartData] = useState<ChartData[]>([
    { name: '1', value: 12000 },
    { name: '2', value: 12100 },
    { name: '3', value: 12150 },
    { name: '4', value: 12300 },
    { name: '5', value: 12450 },
  ]);

  const handleOrderClick = useCallback(() => {
    // 1. Trigger Particle Animation
    const particleId = Date.now();
    setActiveParticles((prev) => [...prev, particleId]);
  }, []);

  const handleParticleComplete = useCallback((id: number) => {
    // Remove particle
    setActiveParticles((prev) => prev.filter((p) => p !== id));

    // 2. Update Backend State (Simulating API success)
    const now = new Date();
    const timeString = now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    const newOrderId = (orderCounter + 1).toString();
    const orderAmount = 85;

    // Update Counter
    setOrderCounter(prev => prev + 1);

    // Update Revenue
    const newRevenue = revenue + orderAmount;
    setRevenue(newRevenue);

    // Update Chart
    setChartData(prev => {
      const newData = [...prev, { name: newOrderId, value: newRevenue }];
      return newData.slice(-15); // Keep chart clean
    });

    // Add New Order
    const newOrder: Order = {
      id: newOrderId,
      product: 'Cappuccino',
      amount: orderAmount,
      time: timeString,
      status: 'Processing'
    };
    setOrders(prev => [newOrder, ...prev]);

    // Add Notification
    const newNotification: Notification = {
      id: `n-${Date.now()}`,
      title: 'New Order Received',
      message: `Cappuccino - 85 UAH`,
      time: timeString
    };
    setNotifications(prev => [newNotification, ...prev]);

  }, [revenue, orderCounter]);

  return (
    <div className="min-h-screen flex items-center justify-center p-4 md:p-8">

      {/* Browser Window Frame */}
      <div className="w-full max-w-6xl bg-white rounded-xl shadow-2xl overflow-hidden border border-gray-300/50 flex flex-col relative" style={{ height: '800px', maxHeight: '90vh' }}>

        {/* Browser Header */}
        <div className="bg-gray-100 border-b border-gray-200 px-4 py-3 flex items-center gap-4 shrink-0">
          <div className="flex gap-2">
            <div className="w-3 h-3 rounded-full bg-red-400 border border-red-500/20"></div>
            <div className="w-3 h-3 rounded-full bg-yellow-400 border border-yellow-500/20"></div>
            <div className="w-3 h-3 rounded-full bg-green-400 border border-green-500/20"></div>
          </div>

          <div className="flex-1 bg-white border border-gray-200 rounded-md px-3 py-1.5 text-xs text-gray-500 flex items-center justify-center font-mono relative shadow-sm">
            <span className="absolute left-3 opacity-50">🔒</span>
            coffeehouse.com/shop/cappuccino
          </div>
          <div className="w-16"></div> {/* Spacer for centering */}
        </div>

        {/* Content Area */}
        <div className="flex-1 flex relative overflow-hidden">
          <ClientPanel onOrder={handleOrderClick} />
          <AdminPanel 
            orders={orders} 
            notifications={notifications} 
            revenue={revenue} 
            chartData={chartData} 
          />

          {/* The Flying Particle Animation Layer */}
          <ParticleOverlay 
            activeParticles={activeParticles} 
            onComplete={handleParticleComplete} 
          />
        </div>

      </div>

      {/* Instructional Tooltip (Optional, for demo context) */}
      <div className="fixed bottom-8 text-center w-full pointer-events-none opacity-50">
        <p className="text-sm text-gray-500">Demo: Click "Замовити" to see the automation flow.</p>
      </div>
    </div>
  );
}

