                    </motion.tr>
                  ))}
                </AnimatePresence>
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useCallback, useEffect } from 'react';
import { Coffee, Hotel, Bike } from 'lucide-react';
