  ],
  hotel: [
    { id: '204', product: 'Люкс', amount: 2500, time: '10:15', status: 'Booked', customerName: 'Іван Д.', meta: '24.10 - 27.10' },
    { id: '203', product: 'Стандарт', amount: 1200, time: '09:30', status: 'Booked', customerName: 'Ольга М.', meta: '25.10 - 26.10' },
