    { id: '891', product: 'Велосипед', amount: 200, time: '09:55', status: 'Rented', meta: 'N/A' },
    { id: '890', product: 'GoPro Hero', amount: 400, time: '09:00', status: 'Rented', meta: '100%' },
  ]
};

export default function App() {
  const [activeScenario, setActiveScenario] = useState<ScenarioType>('coffee');
  const [isMobile, setIsMobile] = useState(false);
  const config = SCENARIOS[activeScenario];

  const [activeParticles, setActiveParticles] = useState<number[]>([]);
  const [revenue, setRevenue] = useState(12450);
  const [orderCounter, setOrderCounter] = useState(1245);
  const [orders, setOrders] = useState<Order[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [chartData, setChartData] = useState<ChartData[]>([
    { name: '1', value: 12000 },
    { name: '2', value: 12100 },
    { name: '3', value: 12150 },
    { name: '4', value: 12300 },
    { name: '5', value: 12450 },
  ]);

  useEffect(() => {
    const checkMobile = () => setIsMobile(window.innerWidth < 768);
    checkMobile();
    window.addEventListener('resize', checkMobile);
    return () => window.removeEventListener('resize', checkMobile);
  }, []);

  // Reset/Load data when scenario changes
  useEffect(() => {
    setOrders(MOCK_DATA[activeScenario] as Order[]);

    // Different "Revenue" metric for Rental (Count instead of Cash)
    if (activeScenario === 'rental') {
      setRevenue(12); // Active rentals count
    } else {
      setRevenue(activeScenario === 'hotel' ? 45000 : 12450);
    }

    setNotifications([{ id: 'init', title: 'Telegram', message: 'Bot: Система готова до роботи', time: '09:00' }]);
    setOrderCounter(parseInt(MOCK_DATA[activeScenario][0].id));
  }, [activeScenario]);

  const handleOrderClick = useCallback(() => {
    const particleId = Date.now();
    setActiveParticles((prev) => [...prev, particleId]);
  }, []);

  const handleParticleComplete = useCallback((id: number) => {
    setActiveParticles((prev) => prev.filter((p) => p !== id));

    const now = new Date();
    const timeString = now.toLocaleTimeString('uk-UA', { hour: '2-digit', minute: '2-digit' });
    const newOrderId = (orderCounter + 1).toString();
    const orderAmount = config.price;

    setOrderCounter(prev => prev + 1);

    // Update "Revenue" logic based on scenario
    let newRevenue = revenue;
    if (activeScenario === 'rental') {
      newRevenue = revenue + 1; // Increment active count
    } else {
      newRevenue = revenue + orderAmount; // Increment money
    }
    setRevenue(newRevenue);

    setChartData(prev => {
      const newData = [...prev, { name: newOrderId, value: newRevenue }];
      return newData.slice(-15);
    });

    // Generate smart data based on scenario
    const newGuest = activeScenario === 'hotel' ? getRandomName() : undefined;
    const newMeta = activeScenario === 'hotel' ? getRandomDate() : activeScenario === 'rental' ? getRandomBattery() : undefined;
    const newProduct = activeScenario === 'hotel' ? 'Люкс #305' : activeScenario === 'rental' ? 'Ninebot Max' : 'Капучино';

    const newOrder: Order = {
      id: newOrderId,
      product: newProduct,
      amount: orderAmount,
      time: timeString,
      status: activeScenario === 'hotel' ? 'Booked' : activeScenario === 'rental' ? 'Rented' : 'Processing',
      customerName: newGuest,
      meta: newMeta
    };
    setOrders(prev => [newOrder, ...prev]);

    // Custom Bot Messages
    let botMsg = '';
    if (activeScenario === 'hotel') {
      botMsg = `Bot: 🛎️ ${config.botPrefix}: ${newGuest} • ${newProduct} • Дати: ${newMeta}`;
    } else if (activeScenario === 'rental') {
      botMsg = `Bot: 🛴 ${config.botPrefix}: ${newProduct} (ID: #${Math.floor(Math.random() * 900) + 100}) • 🔋 ${newMeta} • ${timeString}`;
    } else {
      botMsg = `Bot: ☕ ${config.botPrefix}: ${newProduct} (1 шт) • Сума: ${orderAmount} грн • ${timeString}`;
    }

    const newNotification: Notification = {
      id: `n-${Date.now()}`,
      title: 'Telegram',
      message: botMsg,
      time: timeString
    };
    setNotifications(prev => [newNotification, ...prev]);

  }, [revenue, orderCounter, activeScenario, config]);

  return (
    <div className="min-h-screen flex flex-col items-center justify-center p-4 md:p-8 bg-gray-100 font-sans">

      {/* Industry Switcher */}
      <div className="mb-6 bg-white p-1 rounded-xl shadow-sm border border-gray-200 flex flex-wrap justify-center gap-1">
        {(Object.keys(SCENARIOS) as ScenarioType[]).map((key) => {
          const s = SCENARIOS[key];
          const Icon = s.icon;
          const isActive = activeScenario === key;
          return (
            <button
              key={key}
              onClick={() => setActiveScenario(key)}
              className={`px-4 py-2 rounded-lg text-sm font-medium flex items-center gap-2 transition-all ${
                isActive 
                  ? 'bg-gray-900 text-white shadow-md' 
                  : 'text-gray-500 hover:bg-gray-100'
              }`}
            >
              <Icon size={16} />
              {s.label}
            </button>
          );
        })}
      </div>

      {/* Browser Window Frame */}
      <div className={`w-full max-w-6xl bg-white rounded-xl shadow-2xl overflow-hidden border border-gray-300/50 flex flex-col relative transition-all duration-300 ${isMobile ? 'h-auto min-h-screen' : 'h-[800px] max-h-[90vh]'}`}>

        {/* Browser Header */}
        <div className="bg-gray-100 border-b border-gray-200 px-4 py-3 flex items-center gap-4 shrink-0">
          <div className="flex gap-2">
            <div className="w-3 h-3 rounded-full bg-red-400 border border-red-500/20"></div>
            <div className="w-3 h-3 rounded-full bg-yellow-400 border border-yellow-500/20"></div>
            <div className="w-3 h-3 rounded-full bg-green-400 border border-green-500/20"></div>
          </div>

          <div className="flex-1 bg-white border border-gray-200 rounded-md px-3 py-1.5 text-xs text-gray-500 flex items-center justify-center font-mono relative shadow-sm">
            <span className="absolute left-3 opacity-50">🔒</span>
            business.ua/{activeScenario}/demo
          </div>
          <div className="w-16"></div> 
        </div>

        {/* Content Area */}
        <div className="flex-1 flex flex-col md:flex-row relative overflow-hidden">
          <ClientPanel onOrder={handleOrderClick} config={config} />
          <AdminPanel 
            orders={orders} 
            notifications={notifications} 
            revenue={revenue} 
            chartData={chartData} 
            config={config}
          />

          <ParticleOverlay 
            activeParticles={activeParticles} 
            onComplete={handleParticleComplete} 
            isVertical={isMobile}
          />
        </div>
      </div>

      <div className="fixed bottom-8 text-center w-full pointer-events-none opacity-50 px-4 hidden md:block">
        <p className="text-sm text-gray-500">
          Оберіть індустрію зверху та натисніть кнопку дії, щоб побачити автоматизацію.
        </p>
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { ScenarioType, ScenarioConfig } from '../types';
import { Layers, X } from 'lucide-react';

interface OrbitalMenuProps {
  scenarios: Record<ScenarioType, ScenarioConfig>;
  activeScenario: ScenarioType;
  onSelect: (id: ScenarioType) => void;
}

export const OrbitalMenu: React.FC<OrbitalMenuProps> = ({ scenarios, activeScenario, onSelect }) => {
  const [isOpen, setIsOpen] = useState(false);

  const toggleOpen = () => setIsOpen(!isOpen);

  return (
    <div className="absolute top-4 right-4 z-50 flex flex-col items-end pointer-events-auto">
      <div className="relative">
        <AnimatePresence>
          {isOpen && (
            <motion.div
              initial={{ opacity: 0, scale: 0.8 }}
              animate={{ opacity: 1, scale: 1 }}
              exit={{ opacity: 0, scale: 0.8 }}
              className="absolute top-12 right-0 flex flex-col gap-3 p-2 min-w-[140px]"
            >
              {(Object.keys(scenarios) as ScenarioType[]).map((key, index) => {
                const s = scenarios[key];
                const Icon = s.icon;
                const isActive = activeScenario === key;
                return (
                  <motion.button
                    key={key}
                    initial={{ x: 20, opacity: 0 }}
                    animate={{ x: 0, opacity: 1 }}
                    exit={{ x: 20, opacity: 0 }}
                    transition={{ delay: index * 0.05 }}
                    onClick={() => {
                      onSelect(key);
                      setIsOpen(false);
                    }}
                    className={`flex items-center justify-end gap-3 px-4 py-3 rounded-xl shadow-lg backdrop-blur-md border transition-all
                      ${isActive 
                        ? 'bg-slate-900/90 border-slate-700 text-white' 
                        : 'bg-white/90 border-slate-200 text-slate-600 hover:bg-white'
                      }`}
                  >
                    <span className="text-sm font-medium">{s.label}</span>
                    <Icon size={18} />
                  </motion.button>
                );
              })}
            </motion.div>
          )}
        </AnimatePresence>

        <motion.button
          onClick={toggleOpen}
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
          className={`w-12 h-12 rounded-full shadow-xl flex items-center justify-center border-2 z-50 relative
            ${isOpen ? 'bg-red-500 border-red-400 text-white' : 'bg-slate-900 border-slate-700 text-white'}`}
        >
          <AnimatePresence mode="wait">
            {isOpen ? (
              <motion.div
                key="close"
                initial={{ rotate: -90, opacity: 0 }}
                animate={{ rotate: 0, opacity: 1 }}
                exit={{ rotate: 90, opacity: 0 }}
              >
                <X size={20} />
              </motion.div>
            ) : (
              <motion.div
                key="menu"
                initial={{ rotate: 90, opacity: 0 }}
                animate={{ rotate: 0, opacity: 1 }}
                exit={{ rotate: -90, opacity: 0 }}
              >
                <Layers size={20} />
              </motion.div>
            )}
          </AnimatePresence>
        </motion.button>
      </div>
    </div>
  );
};

