import React from 'react';
import { motion, AnimatePresence } from 'framer-motion';

interface ParticleOverlayProps {
  activeParticles: number[];
  onComplete: (id: number) => void;
  isVertical?: boolean;
}

export const ParticleOverlay: React.FC<ParticleOverlayProps> = ({ activeParticles, onComplete, isVertical = false }) => {
  return (
    <div className="absolute inset-0 pointer-events-none z-50 overflow-hidden">
      <AnimatePresence>
        {activeParticles.map((id) => (
          <motion.div
            key={id}
            initial={isVertical ? {
              left: '50%',
              top: '550px', // Matches the button position in the mobile frame approx
              opacity: 1,
              scale: 0.5,
              x: '-50%',
              boxShadow: "0 0 0px rgba(59, 130, 246, 0)"
            } : { 
              left: '25%', 
              top: '60%', 
              opacity: 1, 
              scale: 0.5,
              x: '0%',
              boxShadow: "0 0 0px rgba(59, 130, 246, 0)"
            }}
            animate={isVertical ? {
              left: '50%',
              top: ['550px', '750px'], // Fly down to the notification area in admin panel
              opacity: [1, 1, 0],
              scale: [1, 1.5, 0.5],
              boxShadow: [
                "0 0 10px rgba(59, 130, 246, 0.5)",
                "0 0 20px rgba(59, 130, 246, 0.8)",
                "0 0 5px rgba(59, 130, 246, 0)"
              ]
            } : { 
              left: ['25%', '50%', '75%'],
              top: ['60%', '50%', '40%'], // Curve path to the phone notification area on desktop
              opacity: [1, 1, 0],
              scale: [1, 1.5, 0.5],
              boxShadow: [
                "0 0 10px rgba(59, 130, 246, 0.5)",
                "0 0 20px rgba(59, 130, 246, 0.8)",
                "0 0 5px rgba(59, 130, 246, 0)"
              ]
            }}
            transition={{ duration: 0.8, ease: "easeInOut" }}
            onAnimationComplete={() => onComplete(id)}
            className="absolute w-4 h-4 bg-blue-500 rounded-full"
          >
            {/* Trail effect */}
            <motion.div 
              className="absolute inset-0 bg-cyan-400 rounded-full blur-sm"
              animate={{ scale: [1, 2, 1] }}
              transition={{ repeat: Infinity, duration: 0.2 }}
            />
          </motion.div>
        ))}
      </AnimatePresence>
    </div>
  );
};

