      setRevenue(activeScenario === 'hotel' ? 45000 : 12450);
    }
    setNotifications([{ id: 'init', title: 'System', message: 'Система готова до роботи', time: '09:00' }]);
    setOrderCounter(parseInt(MOCK_DATA[activeScenario][0].id));
