  const triggerStressTest = useCallback(() => {
    if (isSimulating) return;
    setIsSimulating(true);
    let count = 0;

    // Initial chaos notification
    setNotifications(prev => [{
        id: `stress-start-${Date.now()}`,
        title: 'System Alert',
        message: '⚠️ Warning: Abnormal traffic spike detected!',
        time: new Date().toLocaleTimeString('uk-UA', {hour: '2-digit', minute:'2-digit'})
    }, ...prev]);

    const interval = setInterval(() => {
        count++;

        const now = new Date();
        const timeString = now.toLocaleTimeString('uk-UA', { hour: '2-digit', minute: '2-digit' });
        const newOrderId = `AUTO-${Date.now().toString().slice(-4)}-${count}`;

        const randomItem = config.menu ? config.menu[Math.floor(Math.random() * config.menu.length)] : undefined;
        const amount = randomItem ? randomItem.price : config.price;
        const newProduct = randomItem ? randomItem.name : config.productName;

        // Update Revenue
        setRevenue(prev => activeScenario === 'rental' ? prev + 1 : prev + amount);

        // Update Chart
        setChartData(prev => {
           const lastVal = prev.length > 0 ? prev[prev.length - 1].value : 0;
           const newData = [...prev, { name: count.toString(), value: activeScenario === 'rental' ? lastVal + 1 : lastVal + amount }];
           return newData.slice(-15);
        });

        const newOrder: Order = {
            id: newOrderId,
            product: newProduct,
            amount: amount,
            time: timeString,
            status: 'Processing',
            customerName: getRandomName(),
            meta: activeScenario === 'hotel' ? getRandomDate() : activeScenario === 'rental' ? getRandomBattery() : undefined
        };

        setOrders(prev => [newOrder, ...prev]);

        if (count >= 30) {
            clearInterval(interval);
            setIsSimulating(false);
            setNotifications(prev => [{
                id: `stress-end-${Date.now()}`,
                title: '✅ Auto-Scaling',
                message: 'Traffic normalized. Added 2 worker nodes successfully.',
                time: new Date().toLocaleTimeString('uk-UA', {hour: '2-digit', minute:'2-digit'})
            }, ...prev]);
        }
    }, 150);

  }, [config, activeScenario, isSimulating]);

  const handleParticleComplete = useCallback((id: number) => {
    setActiveParticles((prev) => prev.filter((p) => p !== id));

    const now = new Date();
    const timeString = now.toLocaleTimeString('uk-UA', { hour: '2-digit', minute: '2-digit' });
    const newOrderId = (orderCounter + 1).toString();

    const orderAmount = pendingItem ? pendingItem.price : config.price;

    setOrderCounter(prev => prev + 1);

    let newRevenue = revenue;
    if (activeScenario === 'rental') {
      newRevenue = revenue + 1;
    } else {
      newRevenue = revenue + orderAmount;
    }
    setRevenue(newRevenue);

    setChartData(prev => {
      const newData = [...prev, { name: newOrderId, value: newRevenue }];
      return newData.slice(-15);
    });

    const newGuest = activeScenario === 'hotel' ? getRandomName() : undefined;
    const newMeta = activeScenario === 'hotel' ? getRandomDate() : activeScenario === 'rental' ? getRandomBattery() : undefined;
    const newProduct = pendingItem ? pendingItem.name : (activeScenario === 'hotel' ? 'Люкс #305' : activeScenario === 'rental' ? 'Ninebot Max' : 'Капучино');

    const newOrder: Order = {
      id: newOrderId,
      product: newProduct,
      amount: orderAmount,
      time: timeString,
      status: activeScenario === 'hotel' ? 'Booked' : activeScenario === 'rental' ? 'Rented' : 'Processing',
      customerName: newGuest,
      meta: newMeta
    };
    setOrders(prev => [newOrder, ...prev]);

    // Notifications logic
    const randomEvent = Math.random();
    let notifsToAdd: Notification[] = [];

    let botMsg = '';
    if (activeScenario === 'hotel') {
      botMsg = `Bot: 🛎️ ${config.botPrefix}: ${newGuest} • ${newProduct} • Дати: ${newMeta}`;
    } else if (activeScenario === 'rental') {
      botMsg = `Bot: 🛴 ${config.botPrefix}: ${newProduct} (ID: #${Math.floor(Math.random() * 900) + 100}) • 🔋 ${newMeta}`;
    } else {
      botMsg = `Bot: ☕ ${config.botPrefix}: ${newProduct} (1 шт) • Сума: ${orderAmount} грн`;
    }

    notifsToAdd.push({
      id: `n-${Date.now()}`,
      title: 'Telegram Bot',
      message: botMsg,
      time: timeString
    });

    if (activeScenario === 'coffee' && randomEvent > 0.3) {
       const staffNames = ['Офіціант Андрій', 'Бариста Оля', 'Офіціант Максим'];
       const staffAction = [
         `Продав десерт до кави (+${Math.floor(Math.random() * 50 + 40)} грн)`,
         `Отримав чайові через QR`,
         `Закрив стіл №4`
       ];
       notifsToAdd.push({
         id: `s-${Date.now()}`,
         title: 'Staff Monitor',
         message: `🔔 ${staffNames[Math.floor(Math.random() * staffNames.length)]}: ${staffAction[Math.floor(Math.random() * staffAction.length)]}`,
         time: timeString
       });
    } else if (activeScenario === 'hotel' && randomEvent > 0.5) {
       notifsToAdd.push({
         id: `h-${Date.now()}`,
         title: 'Reception',
         message: `📒 Хостес Ірина: Забронювала столик у ресторані (№7, 19:00)`,
         time: timeString
       });
    }

    setNotifications(prev => [...notifsToAdd, ...prev]);

  }, [revenue, orderCounter, activeScenario, config, pendingItem]);

  return (
    <div className="min-h-screen flex flex-col items-center justify-center p-4 md:p-8 bg-gray-100 font-sans">

      {/* Industry Switcher */}
      <div className="mb-6 bg-white p-1 rounded-xl shadow-sm border border-gray-200 flex flex-wrap justify-center gap-1">
        {(Object.keys(SCENARIOS) as ScenarioType[]).map((key) => {
          const s = SCENARIOS[key];
          const Icon = s.icon;
          const isActive = activeScenario === key;
          return (
            <button
              key={key}
              onClick={() => setActiveScenario(key)}
              className={`px-4 py-2 rounded-lg text-sm font-medium flex items-center gap-2 transition-all ${
                isActive 
                  ? 'bg-gray-900 text-white shadow-md' 
                  : 'text-gray-500 hover:bg-gray-100'
              }`}
            >
              <Icon size={16} />
              {s.label}
            </button>
          );
        })}
      </div>

      {/* Browser Window Frame */}
      <div className={`w-full max-w-6xl bg-white rounded-xl shadow-2xl overflow-hidden border border-gray-300/50 flex flex-col relative transition-all duration-300 ${isMobile ? 'h-auto min-h-screen' : 'h-[800px] max-h-[90vh]'}`}>

        {/* Browser Header */}
        <div className="bg-gray-100 border-b border-gray-200 px-4 py-3 flex items-center gap-4 shrink-0">
          <div className="flex gap-2">
            <div className="w-3 h-3 rounded-full bg-red-400 border border-red-500/20"></div>
            <div className="w-3 h-3 rounded-full bg-yellow-400 border border-yellow-500/20"></div>
            <div className="w-3 h-3 rounded-full bg-green-400 border border-green-500/20"></div>
          </div>

          <div className="flex-1 bg-white border border-gray-200 rounded-md px-3 py-1.5 text-xs text-gray-500 flex items-center justify-center font-mono relative shadow-sm">
            <span className="absolute left-3 opacity-50">🔒</span>
            business.ua/{activeScenario}/demo
          </div>
          <div className="w-16"></div> 
        </div>

        {/* Content Area */}
        <div className="flex-1 flex flex-col md:flex-row relative overflow-hidden">
          <ClientPanel onOrder={handleOrderClick} config={config} />
          <AdminPanel 
            orders={orders} 
            notifications={notifications} 
            revenue={revenue} 
            chartData={chartData} 
            config={config}
            isSimulating={isSimulating}
            onStressTest={triggerStressTest}
          />

          <ParticleOverlay 
            activeParticles={activeParticles} 
            onComplete={handleParticleComplete} 
            isVertical={isMobile}
          />
        </div>
      </div>

      <div className="fixed bottom-8 text-center w-full pointer-events-none opacity-50 px-4 hidden md:block">
        <p className="text-sm text-gray-500">
          Оберіть індустрію зверху та натисніть кнопку дії, щоб побачити автоматизацію.
        </p>
      </div>
    </div>
  );
}

