               <button className="p-1.5 hover:bg-slate-700 rounded text-slate-400 hover:text-amber-400 transition-colors" title="Print Check">
                 <Printer size={14} />
               </button>
            </td>
          </>
        );
    }
  };

  return (
    <div className={`w-full md:w-1/2 bg-slate-900 text-slate-100 flex flex-col p-6 md:p-8 relative overflow-hidden transition-colors duration-500 border-l ${isSimulating ? 'border-red-500 shadow-[inset_10px_0_50px_rgba(239,68,68,0.1)]' : 'border-transparent'}`}>
