      <div className={`absolute top-0 right-0 w-64 h-64 rounded-full blur-3xl -translate-y-1/2 translate-x-1/2 pointer-events-none opacity-20 transition-colors duration-500
        ${isSimulating ? 'bg-red-500 animate-pulse' : config.colorTheme === 'rose' ? 'bg-rose-500' : config.colorTheme === 'indigo' ? 'bg-indigo-500' : 'bg-amber-500'}`}>
      </div>

      {/* Header */}
      <div className="flex justify-between items-center mb-6 md:mb-8 pb-4 border-b border-slate-800 z-10">
        <div className="flex items-center gap-2">
          <Database className={isSimulating ? 'text-red-500 animate-pulse' : config.colorTheme === 'rose' ? 'text-rose-400' : config.colorTheme === 'indigo' ? 'text-indigo-400' : 'text-amber-400'} size={20} />
          <span className="font-semibold tracking-wide uppercase text-sm md:text-base">{config.adminTitle}</span>
        </div>
        <div className="flex items-center gap-4">
            <button 
                onClick={onStressTest}
                disabled={isSimulating}
                className={`
                    flex items-center gap-1.5 px-3 py-1.5 rounded text-[10px] font-bold uppercase tracking-wider transition-all
                    ${isSimulating 
                        ? 'bg-red-500/20 text-red-400 cursor-not-allowed border border-red-500/50' 
                        : 'bg-slate-800 text-slate-400 hover:bg-red-500/20 hover:text-red-400 border border-slate-700 hover:border-red-500/50'}
                `}
            >
                {isSimulating ? <Activity size={12} className="animate-spin" /> : <Zap size={12} />}
                {isSimulating ? 'ТЕСТУВАННЯ...' : 'Стрес-тест'}
