            <div className={`flex items-center gap-2 text-xs font-mono transition-colors ${isSimulating ? 'text-red-400 font-bold' : 'text-slate-400'}`}>
                <div className={`w-2 h-2 rounded-full ${isSimulating ? 'bg-red-500 animate-[ping_1s_ease-in-out_infinite]' : 'bg-green-500 animate-pulse'}`}></div>
                {isSimulating ? 'ПІКОВЕ НАВАНТАЖЕННЯ' : 'ОНЛАЙН'}
