                src="https://images.unsplash.com/photo-1555421689-d68471e189f2?auto=format&fit=crop&q=80&w=400" 
                className="absolute inset-0 w-full h-full object-cover opacity-20"
                alt="Wallpaper"
              />

              <div className="relative z-10 space-y-3">
                <div className="text-center text-white/50 text-xs font-medium mb-4">
                  {new Date().toLocaleTimeString('uk-UA', {hour: '2-digit', minute:'2-digit'})}
                </div>

                <AnimatePresence>
                  {notifications.slice(0, 3).map((notif) => (
                    <motion.div
                      key={notif.id}
                      initial={{ x: 50, opacity: 0, filter: 'blur(10px)' }}
                      animate={{ x: 0, opacity: 1, filter: 'blur(0px)' }}
                      exit={{ x: -50, opacity: 0 }}
                      className={`
                        backdrop-blur-md border p-3 rounded-xl shadow-lg
                        ${notif.title === 'Системна Тривога' 
                            ? 'bg-red-500/20 border-red-500/40' 
                            : notif.title === '✅ Авто-масштабування' 
                                ? 'bg-green-500/20 border-green-500/40' 
                                : 'bg-white/10 border-white/20'}
                      `}
                    >
                      <div className="flex items-start gap-3">
                        <div className={`
                            p-1.5 rounded-full shrink-0 flex items-center justify-center
                            ${notif.title === 'Системна Тривога' ? 'bg-red-500' : notif.title === '✅ Авто-масштабування' ? 'bg-green-500' : 'bg-sky-500'}
                        `}>
                          {notif.title === 'Системна Тривога' ? <AlertTriangle size={12} className="text-white" /> : <Send size={12} className="text-white fill-white pr-0.5 pt-0.5" />}
                        </div>
                        <div className="overflow-hidden w-full">
                          <div className="flex justify-between items-baseline">
                            <h4 className="text-xs font-bold text-white">{notif.title}</h4>
                            <span className="text-[9px] text-slate-400 ml-2">now</span>
                          </div>
                          <p className="text-[10px] text-slate-200 leading-tight mt-0.5 opacity-90 break-words">
                            {notif.message}
                          </p>
                        </div>
                      </div>
                    </motion.div>
                  ))}
                </AnimatePresence>
              </div>
            </div>
          </div>

          {/* Business Specific Widget Card */}
          <div className={`w-full md:w-1/2 bg-slate-800/50 rounded-2xl border p-5 flex flex-col backdrop-blur-sm h-48 md:h-auto transition-all duration-300 hover:scale-[1.02] hover:shadow-2xl ${isSimulating ? 'border-red-500/30' : 'border-slate-700 hover:border-slate-600'}`}>
             <div className="mb-4">
               <h3 className="text-slate-400 text-xs font-semibold uppercase tracking-wider mb-1">
                 {config.id === 'coffee' ? 'Каса (Готівка + Карта)' : config.id === 'hotel' ? 'Статус Готелю' : 'Стан Флоту'}
               </h3>
               {config.id === 'coffee' && (
                 <div className="flex items-baseline gap-1 relative">
                   <span className={`text-2xl font-bold transition-all ${isSimulating ? 'text-red-400 scale-110' : 'text-white'}`}>{revenue.toLocaleString('uk-UA')}</span>
                   <span className="text-sm text-slate-400">грн</span>

                   {/* Floating Profit Animation */}
                   <AnimatePresence>
                    {floatingProfits.map(p => (
                      <motion.div
                        key={p.id}
                        initial={{ opacity: 0, y: 10, scale: 0.5 }}
                        animate={{ opacity: 1, y: -20, scale: 1.2 }}
                        exit={{ opacity: 0, y: -40 }}
                        transition={{ duration: 1 }}
                        className="absolute left-0 -top-8 text-green-400 font-bold text-lg"
                      >
                        +{p.value}
                      </motion.div>
                    ))}
                   </AnimatePresence>
                 </div>
               )}
             </div>

             <div className="flex-1 min-h-0">
                {config.id === 'hotel' ? renderHotelWidget() : config.id === 'rental' ? renderRentalWidget() : renderTerminalWidget()}
             </div>
          </div>
        </div>

        {/* Bottom Section: CRM Table */}
        <div className={`flex-1 bg-slate-800/50 rounded-2xl border overflow-hidden flex flex-col backdrop-blur-sm h-64 md:h-auto min-h-0 transition-colors duration-300 ${isSimulating ? 'border-red-500/30' : 'border-slate-700'}`}>
          <div className="px-5 py-3 border-b border-slate-700 bg-slate-800/80 flex justify-between items-center shrink-0">
             <span className="text-xs font-semibold text-slate-300 uppercase">
               {config.id === 'coffee' ? 'Черга замовлень' : config.id === 'hotel' ? 'Графік заїздів' : 'Активні сесії'}
             </span>
             <div className="flex gap-2">
               <div className="w-2 h-2 rounded-full bg-red-400"></div>
               <div className="w-2 h-2 rounded-full bg-yellow-400"></div>
               <div className="w-2 h-2 rounded-full bg-green-400"></div>
             </div>
          </div>

          <div className="flex-1 overflow-y-auto crm-scroll p-0">
            <table className="w-full text-left border-collapse">
              <thead className="sticky top-0 bg-slate-800/95 backdrop-blur-sm z-10 shadow-sm">
                <tr className="text-xs text-slate-500 border-b border-slate-700/50">
                  {renderTableHeaders()}
                  <th className="py-3 pr-5 text-right font-medium">Стан</th>
                </tr>
              </thead>
              <tbody className="text-sm">
                <AnimatePresence initial={false} mode="popLayout">
                  {orders.map((order) => (
                    <motion.tr
                      key={order.id}
                      initial={{ opacity: 0, y: -20, backgroundColor: "rgba(255, 255, 255, 0.05)" }}
                      animate={{ opacity: 1, y: 0, backgroundColor: "transparent" }}
                      transition={{ duration: 0.4 }}
                      layout
                      className="border-b border-slate-700/30 group hover:bg-slate-700/30 transition-colors"
                    >
                      {renderTableRows(order)}
                      <td className="py-3 pr-5 text-right">
                        <span className={`inline-flex items-center px-2 py-0.5 rounded text-xs font-medium border ${getStatusColor(order.status)}`}>
                          {getStatusLabel(order.status)}
                        </span>
                      </td>
                    </motion.tr>
                  ))}
                </AnimatePresence>
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
}

import React, { useState, useCallback, useEffect } from 'react';
