    { id: '1244', product: 'Еспресо', amount: 45, time: '10:42', status: 'Completed' },
    { id: '1243', product: 'Лате', amount: 65, time: '10:30', status: 'Completed' },
    { id: '1242', product: 'Американо', amount: 40, time: '10:15', status: 'Completed' },
